type AppRollbackValidationConditionCodeEnum string

const (
	AppRollbackValidationConditionCodeEnumIncompatiblePhase         AppRollbackValidationConditionCodeEnum = "incompatible_phase"
	AppRollbackValidationConditionCodeEnumIncompatibleResult        AppRollbackValidationConditionCodeEnum = "incompatible_result"
	AppRollbackValidationConditionCodeEnumExceededRevisionLimit     AppRollbackValidationConditionCodeEnum = "exceeded_revision_limit"
	AppRollbackValidationConditionCodeEnumAppPinned                 AppRollbackValidationConditionCodeEnum = "app_pinned"
	AppRollbackValidationConditionCodeEnumDatabaseConfigConflict    AppRollbackValidationConditionCodeEnum = "database_config_conflict"
	AppRollbackValidationConditionCodeEnumRegionConflict            AppRollbackValidationConditionCodeEnum = "region_conflict"
	AppRollbackValidationConditionCodeEnumStaticSiteRequiresRebuild AppRollbackValidationConditionCodeEnum = "static_site_requires_rebuild"
	AppRollbackValidationConditionCodeEnumImageSourceMissingDigest  AppRollbackValidationConditionCodeEnum = "image_source_missing_digest"
)
